package com.printflow;
import com.printflow.files.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class ReferenceReviewTest {
 @TempDir Path folder;
 @Test void fictionalSamplesCoverEightCategoriesAndProduceReadableImages()throws Exception{var samples=ArtworkSamples.list("");assertEquals(8,samples.size());var hashes=new HashSet<String>();for(var s:samples){byte[] png=ArtworkSamples.png(s.get("code"));assertEquals(600,javax.imageio.ImageIO.read(new java.io.ByteArrayInputStream(png)).getWidth());hashes.add(Base64.getEncoder().encodeToString(java.security.MessageDigest.getInstance("SHA-256").digest(png)));}assertEquals(8,hashes.size());assertThrows(NoSuchElementException.class,()->ArtworkSamples.png("unknown"));}
 @Test void pdfReviewPreservesPagesAndSourceAndAddsUnicodePagePinsWithoutActions()throws Exception{Path source=folder.resolve("source.pdf");try(var doc=new org.apache.pdfbox.pdmodel.PDDocument()){for(int n=0;n<2;n++){var page=new org.apache.pdfbox.pdmodel.PDPage();doc.addPage(page);try(var c=new org.apache.pdfbox.pdmodel.PDPageContentStream(doc,page)){c.beginText();c.setFont(new org.apache.pdfbox.pdmodel.font.PDType1Font(org.apache.pdfbox.pdmodel.font.Standard14Fonts.FontName.HELVETICA),12);c.newLineAtOffset(50,700);c.showText("SOURCE "+n);c.endText();}}doc.getDocumentCatalog().setOpenAction(new org.apache.pdfbox.pdmodel.interactive.action.PDActionJavaScript("app.alert('never copy')"));doc.save(source.toFile());}byte[] original=Files.readAllBytes(source);byte[] copy=new ReferenceReviewPdf().create(source,"application/pdf","{\"note\":\"Change colour\",\"pins\":[{\"page\":2,\"x\":0.5,\"y\":0.5,\"text\":\"Change name — বাংলা\"}]}");assertArrayEquals(original,Files.readAllBytes(source));try(var doc=org.apache.pdfbox.Loader.loadPDF(copy)){assertEquals(2,doc.getNumberOfPages());assertNull(doc.getDocumentCatalog().getOpenAction());assertEquals(0,doc.getPage(0).getAnnotations().size());assertTrue(doc.getPage(1).getAnnotations().getFirst().getContents().contains("বাংলা"));assertTrue(new org.apache.pdfbox.text.PDFTextStripper().getText(doc).contains("SOURCE 1"));}}
 @Test void imageReviewAndInvalidDocumentAreBounded()throws Exception{Path source=folder.resolve("image.blob");Files.write(source,ArtworkSamples.png("WEDDING_CARDS"));byte[] copy=new ReferenceReviewPdf().create(source,"image/png","{\"note\":\"Test\",\"pins\":[{\"page\":1,\"x\":0.25,\"y\":0.75,\"text\":\"Here\"}]}");try(var doc=org.apache.pdfbox.Loader.loadPDF(copy)){assertEquals(1,doc.getNumberOfPages());assertEquals(1,doc.getPage(0).getAnnotations().size());}Files.writeString(source,"invalid");assertThrows(java.io.IOException.class,()->new ReferenceReviewPdf().create(source,"application/pdf","{\"pins\":[]}"));try(var paths=Files.list(folder)){assertEquals(1,paths.count());}}
}
